L3_cloud_cluster_quote.invariants_dsl:
spec NodeProfile {    field vcpu_cores: Number {}
    field ram_gb: Number {}
    invariant node_hardware_balance {
        this.vcpu_cores >= 2.0;
        this.vcpu_cores <= 64.0;
        this.ram_gb >= this.vcpu_cores * 2.0;
        this.ram_gb <= 256.0;
    }
}

spec StorageProfile {
    field storage_tb: Number {}
    field redundancy: String {
        value IN ["Standard-LRS", "Geo-Redundant"];
    }
    invariant capacity_limits {
        this.storage_tb >= 1.0;
        this.storage_tb <= 100.0;
    }
}

spec CloudClusterQuote {
    field total_monthly_bill: Number {
        value == this.compute_cost + this.storage_cost;
    }
    field compute_cost: Number {
        value == (this.profile.vcpu_cores * 15.0 + this.profile.ram_gb * 4.0) * this.node_count;
    }
    field storage_cost: Number {
        value == this.storage.storage_tb * 65.0;
    }
    field node_count: Number {}
    field profile: NodeProfile {}
    field storage: StorageProfile {}
    invariant cluster_scale {
        this.node_count >= 2.0;
        this.node_count <= 16.0;
    }
}

L3_clinical_drug_dosage.invariants_dsl:
spec PatientBiometrics {
    field weight_kg: Number {}
    field age_years: Integer {}
    field serum_creatinine: Number {}
    invariant patient_bounds {
        this.weight_kg >= 40.0;
        this.weight_kg <= 160.0;
        this.age_years >= 18;
        this.age_years <= 90;
        this.serum_creatinine >= 0.5;
        this.serum_creatinine <= 3.0;
    }
}

spec DrugRegimen {
    field total_daily_dose_mg: Number {
        value == this.single_dose_mg * this.doses_per_day;
    }
    field single_dose_mg: Number {
        value == this.patient.weight_kg * this.dose_per_kg_mg;
    }
    field dose_per_kg_mg: Number {}
    field doses_per_day: Integer {}
    field administration_route: String {
        value IN ["ORAL_TABLET", "IV_INFUSION"];
    }
    field patient: PatientBiometrics {}
    invariant regimen_limits {
        this.dose_per_kg_mg >= 1.5;
        this.dose_per_kg_mg <= 8.0;
        this.doses_per_day >= 1;
        this.doses_per_day <= 4;
    }
}

L3_portfolio_rebalance.invariants_dsl:
spec AssetAllocation {
    field equity_pct: Number {}
    field bond_pct: Number {}
    invariant allocation_bounds {
        this.equity_pct >= 20.0;
        this.equity_pct <= 80.0;
        this.bond_pct >= 20.0;
        this.bond_pct <= 80.0;
    }
}

spec PortfolioRebalance {
    field total_execution_fee: Number {
        value == this.equity_fee + this.bond_fee;
    }
    field equity_fee: Number {
        value == (this.total_portfolio_usd * (this.allocation.equity_pct / 100.0)) * 0.002;
    }
    field bond_fee: Number {
        value == (this.total_portfolio_usd * (this.allocation.bond_pct / 100.0)) * 0.0005;
    }
    field total_portfolio_usd: Number {}
    field strategy_name: String {
        value IN ["CAPITAL_PRESERVATION", "BALANCED_GROWTH", "AGGRESSIVE_EXPANSION"];
    }
    field allocation: AssetAllocation {}
    invariant portfolio_limits {
        this.total_portfolio_usd >= 10000.0;
        this.total_portfolio_usd <= 5000000.0;
    }
}
